    ExternalName: asset.externalName ?? "",
    CredentialStoreId: asset.credentialStoreId ?? null,
    AllowDirectApiAccess: asset.allowDirectApiAccess ?? false,
    Tags: (asset.tags ?? []).map((t) => t.name ?? ""),
