// src/utils/parse-tags.ts
function parseTags(raw) {
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      throw new Error("Tags must be a JSON array.");
    }
    return parsed;
  } catch {
    throw new Error(`Invalid --tags value. Expected JSON array, e.g. '[{"name":"env","value":"prod"}]'.`);
  }
}

