function formatBucket(bucket) {
  return {
    Key: bucket.identifier ?? "",
    Id: bucket.id ?? "",
    Name: bucket.name ?? "",
    Description: bucket.description ?? "",
    Options: bucket.options ?? "",
    StorageProvider: bucket.storageProvider ?? "",
    FoldersCount: bucket.foldersCount ?? 0,
    Encrypted: bucket.encrypted ?? false
  };
}
function formatBucketDetail(bucket) {
  return {
    ...formatBucket(bucket),
    StorageContainer: bucket.storageContainer ?? "",
    StorageParameters: bucket.storageParameters ?? "",
    ExternalName: bucket.externalName ?? "",
    CredentialStoreId: bucket.credentialStoreId ?? null,
    Tags: (bucket.tags ?? []).map((t) => t.name ?? "")
  };
}
