// src/utils/calendar-resolver.ts
async function resolveCalendar(calendarKey, options) {
  if (!isGuid(calendarKey)) {
    throw new Error(`Invalid calendar key '${calendarKey}': must be a valid UUID. Use 'calendars list' to find calendar keys.`);
  }
  const [apiError, api] = await catchError(createApiClient(CalendarsApi, { tenant: options?.tenant }));
  if (apiError) {
    throw new Error(`Failed to create Calendars API client: ${apiError.message}`);
  }
  const [error, result] = await catchError(api.calendarsGet({
    $filter: `Key eq ${calendarKey}`,
    $top: 1
  }));
  if (error) {
    const errorMessage2 = await extractErrorMessage(error);
    throw new Error(`Failed to resolve calendar '${calendarKey}': ${errorMessage2}`);
  }
  const summary = result.value?.[0];
  if (!summary?.id) {
    throw new Error(`Calendar not found for key: '${calendarKey}'. Use 'calendars list' to find available calendars.`);
  }
  const [detailError, calendar] = await catchError(api.calendarsGetById({ key: summary.id }));
  if (detailError) {
    const errorMessage2 = await extractErrorMessage(detailError);
    throw new Error(`Failed to resolve calendar '${calendarKey}': ${errorMessage2}`);
  }
  return {
    id: calendar.id ?? summary.id,
    key: calendar.key || summary.key || calendarKey,
    name: calendar.name || "",
    calendar
  };
}

// src/commands/calendars.ts
function formatCalendarRow(cal) {
  return {
    Key: cal.key || "",
    Id: cal.id ?? "",
    Name: cal.name || "",
    TimeZoneId: cal.timeZoneId || ""
  };
}
function formatCalendarDetail(cal) {
  return {
    ...formatCalendarRow(cal),
    ExcludedDates: cal.excludedDates ?? []
  };
}
