function registerEvalRunCommand(program2) {
  const evalCmd = program2.command("eval").description("Run offline evaluations for Orchestrator packages. " + "Resolves the package from your personal workspace automatically.");
  evalCmd.command("run-offline-evals").description("Submit an offline eval run for an Orchestrator package.").requiredOption("--package-name <name>", "Orchestrator package name (processKey, e.g. MyAutomation.Agent.agent)").requiredOption("--package-version <version>", "Package version (e.g. 1.0.0)").option("--eval-set-id <id>", "Eval set ID to run; mutually exclusive with --items/--evaluators").option("--items <json>", `JSON array of items to override those from the package (e.g. '[{"input":"hello"}]')`).option("--evaluators <json>", "JSON array of evaluator configs to override those from the package").option("--batch-size <n>", "Max concurrent evaluation pipelines", "5").option("--folder-key <key>", "Folder key (GUID); defaults to personal workspace. Use 'uip or folders list' to find available keys.").option("--is-low-code-agent", "Transform items and evaluators from the package/portal flat format to the API wire format before submitting. " + "Use this when pasting evaluators directly from the package (flat JSON with 'type' and 'category' fields). " + "Wraps each evaluator as { id, evaluatorTypeId, evaluatorConfig } and renames expectedAgentBehavior → expectedBehavior on items.", false).option("--tenant <tenant>", "UiPath tenant name").examples(EVAL_RUN_EXAMPLES).trackedAction(processContext, async (options) => {
    let items;
    let evaluators;
    if (options.items) {
      const result = parseJsonArray(options.items, "--items");
      if (result === null) {
        processContext.exit(1);
        return;
      }
      items = result;
    }
    if (options.evaluators) {
      const result = parseJsonArray(options.evaluators, "--evaluators");
      if (result === null) {
        processContext.exit(1);
        return;
      }
      evaluators = result;
    }
    if (options.evalSetId && (items ?? evaluators)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "--eval-set-id and --items/--evaluators are mutually exclusive.",
        Instructions: "Use --eval-set-id to load items and evaluators from a saved eval set, " + "or use --items/--evaluators to provide them inline. Not both."
      });
      processContext.exit(1);
      return;
    }
    if (!options.evalSetId && !items && !evaluators) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Must provide either --eval-set-id or both --items and --evaluators.",
        Instructions: "Use --eval-set-id to run against a saved eval set, " + "or provide both --items and --evaluators inline."
      });
      processContext.exit(1);
      return;
    }
    if (!!items !== !!evaluators) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "--items and --evaluators must be provided together.",
        Instructions: "Provide both --items and --evaluators, or neither."
      });
      processContext.exit(1);
      return;
    }
    if (options.isLowCodeAgent) {
      if (items)
        items = transformLegacyItems(items);
      if (evaluators)
        evaluators = transformLegacyEvaluators(evaluators);
    }
    const [authErr, ctx] = await catchError(getAuthContext({
      tenant: options.tenant,
      ensureTokenValidityMinutes: 10,
      requireOrganizationId: true,
      requireTenantName: true,
      requireTenantId: true
    }));
    if (authErr) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Authentication failed: ${authErr.message}`,
        Instructions: "Run 'uip login' first."
      });
      processContext.exit(1);
      return;
    }
    const agentsApiBase = `${ctx.baseUrl}/${ctx.organizationId}/${ctx.tenantName}/agentsruntime_/api`;
    const authHeaders = {
      Authorization: `Bearer ${ctx.accessToken}`,
      "Content-Type": "application/json",
      Accept: "application/json",
      "X-UiPath-Internal-TenantId": ctx.tenantId ?? "",
      "X-UiPath-Internal-AccountId": ctx.organizationId ?? ""
    };
    let folderKey;
    let folderLabel;
    if (options.folderKey) {
      folderKey = options.folderKey;
      folderLabel = folderKey;
    } else {
      const [wsApiErr, wsApi] = await catchError(createApiClient(PersonalWorkspacesApi, {
        tenant: options.tenant
      }));
      if (wsApiErr) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: await extractErrorMessage(wsApiErr),
          Instructions: "Run 'uip login' and retry."
        });
        processContext.exit(1);
        return;
      }
      const [wsErr, personalWs] = await catchError(wsApi.personalWorkspacesGetPersonalWorkspace());
      if (wsErr ?? !personalWs?.key) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: `Failed to resolve personal workspace: ${wsErr ? await extractErrorMessage(wsErr) : "not found"}`,
          Instructions: "Ensure your account has a personal workspace enabled."
        });
        processContext.exit(1);
        return;
      }
      folderKey = personalWs.key;
      folderLabel = personalWs.name ?? folderKey;
    }
    const batchSize = Number.parseInt(options.batchSize, 10);
    if (Number.isNaN(batchSize)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Invalid --batch-size "${options.batchSize}": must be a positive integer.`,
        Instructions: "Example: --batch-size 10"
      });
      processContext.exit(1);
      return;
    }
    const evalSetId = options.evalSetId ?? ZERO_GUID;
    const [submitErr, evalSetRunId] = await catchError(submitRun(evalSetId, items, evaluators, batchSize, agentsApiBase, authHeaders, folderKey, ctx.tenantId ?? "", options.packageName, options.packageVersion));
    if (submitErr) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: submitErr.message,
        Instructions: "Check that the package is published and the eval set ID is correct."
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "EvalRunSubmitted",
      Data: {
        Package: `${options.packageName} v${options.packageVersion}`,
        Folder: folderLabel,
        EvalSetId: evalSetId,
        EvalSetRunId: evalSetRunId
      }
    });
  });
}

