// src/utils/attachment-downloader.ts
async function downloadAttachment(attachmentId, outputPath, options) {
  const [apiError, api] = await catchError(createApiClient(AttachmentsApi, { tenant: options.tenant }));
  if (apiError) {
    throw new Error(`Failed to create Attachments API client: ${apiError.message}`);
  }
  const [downloadError, response] = await catchError(api.attachmentsDownloadAttachmentFileByIdRaw({ id: attachmentId }));
  if (downloadError) {
    const errorMessage2 = await extractErrorMessage(downloadError);
    throw new Error(`Failed to download attachment '${attachmentId}': ${errorMessage2}`);
  }
  const redirectUrl = response.raw.headers.get("Location") || response.raw.url;
  if (!redirectUrl) {
    throw new Error(`No download URL returned for attachment '${attachmentId}'. It may have been deleted.`);
  }
  const [fetchError, fileResponse] = await catchError(fetch(redirectUrl));
  if (fetchError) {
    throw new Error(`Failed to fetch attachment file: ${fetchError.message}`);
  }
  if (!fileResponse.ok) {
    throw new Error(`HTTP ${fileResponse.status} fetching attachment: ${fileResponse.statusText}`);
  }
  const [bufferError, buffer] = await catchError(fileResponse.arrayBuffer());
  if (bufferError) {
    throw new Error(`Failed to read attachment data: ${bufferError.message}`);
  }
  const { getFileSystem: getFileSystem2 } = await Promise.resolve().then(() => (init_src(), exports_src));
  const fs7 = getFileSystem2();
  const [writeError] = await catchError(fs7.writeFile(outputPath, Buffer.from(buffer)));
  if (writeError) {
    throw new Error(`Failed to write to '${outputPath}': ${writeError.message}`);
  }
  return {
    attachmentId,
    fileName: outputPath,
    size: buffer.byteLength
  };
}

// src/utils/attachment-uploader.ts
async function uploadAttachment(filePath, name, options) {
  const { getFileSystem: getFileSystem2 } = await Promise.resolve().then(() => (init_src(), exports_src));
  const fs7 = getFileSystem2();
  const [readError, fileBuffer] = await catchError(fs7.readFile(filePath));
  if (readError) {
    throw new Error(`Cannot read file '${filePath}': ${readError.message}`);
  }
  if (fileBuffer === null) {
    throw new Error(`Cannot read file '${filePath}': file is empty or unreadable.`);
  }
  const reference = await uploadJobAttachment(fileBuffer, name, options);
  return reference.ID;
}
async function uploadBuffer(buffer, name, options) {
  const reference = await uploadJobAttachment(buffer, name, options);
  logger.info(`Auto-offloaded to attachment ${reference.ID}`);
  return reference.ID;
}
var INPUT_ARGS_MAX_LENGTH = 1e4;
async function resolveJobInput(inputArguments, inputFilePath, options) {
  if (inputArguments && inputFilePath) {
    throw new Error("--input-arguments and --input-file are mutually exclusive. Use one or the other.");
  }
  if (inputFilePath) {
    const attachmentId = await uploadAttachment(inputFilePath, "input-file", options);
    return { inputFile: attachmentId };
  }
  if (inputArguments && inputArguments.length > INPUT_ARGS_MAX_LENGTH) {
    logger.info(`Input arguments exceed ${INPUT_ARGS_MAX_LENGTH} chars, uploading as InputFile...`);
    const buffer = Buffer.from(inputArguments, "utf-8");
    const attachmentId = await uploadBuffer(buffer, "input-arguments.json", options);
    return { inputFile: attachmentId };
  }
  return { inputArguments };
}
async function parseAttachmentArg(arg) {
  const eqIndex = arg.indexOf("=");
  if (eqIndex > 0) {
    const name = arg.substring(0, eqIndex);
    const path3 = arg.substring(eqIndex + 1);
    if (!name || !path3) {
      throw new Error(`Invalid --attachment format: '${arg}'. Expected 'name=path' or just 'path'.`);
    }
    return { name, path: path3 };
  }
  const { getFileSystem: getFileSystem2 } = await Promise.resolve().then(() => (init_src(), exports_src));
  const fs7 = getFileSystem2();
  return { name: fs7.path.basename(arg), path: arg };
}

// src/utils/job-waiter.ts
var TERMINAL_STATES = ["Successful", "Faulted", "Stopped"];
var isTerminalJobState = (state) => TERMINAL_STATES.includes(state ?? "");
var SUBSTATE_WITH_FAULTS = "WITH_FAULTS";
async function waitForJob(jobKey, options) {
  const result = await pollUntil({
    fn: async () => {
      const resolved = await resolveJob(jobKey, {
        tenant: options.tenant
      });
      return resolved.job;
    },
    until: (job) => isTerminalJobState(job.state) || job.subState === SUBSTATE_WITH_FAULTS,
    getStatus: (job) => {
      if (job.subState === SUBSTATE_WITH_FAULTS) {
        return `${job.state || "Unknown"} (subState: WITH_FAULTS)`;
      }
      return job.state || "Unknown";
    },
    label: `job ${jobKey}`,
    logPrefix: "jobs",
    intervalMs: options.intervalMs,
    timeoutMs: options.timeoutMs,
    maxConsecutiveErrors: 3,
    signal: processContext.pollSignal
  });
  return {
    outcome: result.outcome,
    job: result.data,
    elapsedMs: result.elapsedMs,
    error: result.error
  };
}

// src/utils/machine-resolver.ts
async function resolveMachine(machineKey, options) {
  if (!isGuid(machineKey)) {
    throw new Error(`Invalid machine key '${machineKey}': must be a valid UUID (e.g., '12345678-1234-1234-1234-123456789abc'). Use 'machines list' to find machine keys.`);
  }
  const [apiError, api] = await catchError(createApiClient(MachinesApi, { tenant: options?.tenant }));
  if (apiError) {
    throw new Error(`Failed to create Machines API client: ${apiError.message}`);
  }
  const [getError, result] = await catchError(api.machinesGet({
    $filter: `Key eq ${machineKey}`,
    $top: 1
  }));
  if (getError) {
    const errorMessage2 = await extractErrorMessage(getError);
    throw new Error(`Machine with key '${machineKey}' not found: ${errorMessage2}`);
  }
  const machines = result.value ?? [];
  if (machines.length === 0) {
    throw new Error(`Machine with key '${machineKey}' not found. Use 'machines list' to find machine keys.`);
  }
  const machine = machines[0];
  if (machine.id === undefined || machine.id === null) {
    throw new Error(`Machine '${machineKey}' found but has no numeric ID — cannot resolve.`);
  }
  return toResolved(machine, machineKey);
}
async function resolveMachines(machineKeys, options) {
  for (const key of machineKeys) {
    if (!isGuid(key)) {
      throw new Error(`Invalid machine key '${key}': must be a valid UUID. Use 'machines list' to find machine keys.`);
    }
  }
  const [apiError, api] = await catchError(createApiClient(MachinesApi, { tenant: options?.tenant }));
  if (apiError) {
    throw new Error(`Failed to create Machines API client: ${apiError.message}`);
  }
  const keyList = machineKeys.join(",");
  const [getError, result] = await catchError(api.machinesGet({
    $filter: `Key in (${keyList})`,
    $top: machineKeys.length
  }));
  if (getError) {
    const errorMessage2 = await extractErrorMessage(getError);
    throw new Error(`Error resolving machines: ${errorMessage2}`);
  }
  const machines = result.value ?? [];
  const byKey = new Map;
  for (const m of machines) {
    if (m.key) {
      byKey.set(m.key.toLowerCase(), m);
    }
  }
  const resolved = [];
  for (const key of machineKeys) {
    const machine = byKey.get(key.toLowerCase());
    if (!machine) {
      throw new Error(`Machine with key '${key}' not found. Use 'machines list' to find machine keys.`);
    }
    if (machine.id === undefined || machine.id === null) {
      throw new Error(`Machine '${key}' found but has no numeric ID — cannot resolve.`);
    }
    resolved.push(toResolved(machine, key));
  }
  return resolved;
}
function toResolved(machine, inputKey) {
  return {
    id: machine.id,
    key: machine.key || inputKey,
    name: machine.name || "",
    machine
  };
}

