async function buildJobCompletionOutput(job, elapsedMs, options) {
  const data = {
    ...formatJobDetail(job)
  };
  if (elapsedMs !== undefined) {
    data.Duration = `${Math.round(elapsedMs / 1000)}s`;
  }
  if (job.outputFile && options.download !== false) {
    const { getFileSystem: getFileSystem2 } = await Promise.resolve().then(() => (init_src(), exports_src));
    const fsHelper = getFileSystem2();
    const outputDir = options.outputDir || ".";
    const fileName = fsHelper.path.join(outputDir, `output-${job.key || "job"}.dat`);
    const [dlError, dlResult] = await catchError(downloadAttachment(job.outputFile, fileName, {
      tenant: options.tenant
    }));
    if (dlError) {
      logger.warn(`Failed to download OutputFile: ${dlError.message}`);
      data.OutputFile = job.outputFile;
    } else {
      data.OutputFile = {
        AttachmentId: dlResult.attachmentId,
        DownloadedTo: dlResult.fileName,
        Size: dlResult.size
      };
    }
  } else if (job.outputFile) {
    data.OutputFile = job.outputFile;
  }
  return data;
}

