// src/commands/processes.ts
function formatProcess(release) {
  return {
    Key: release.key || "",
    Name: release.name || "",
    ProcessKey: release.processKey || "",
    ProcessVersion: release.processVersion || "",
    Description: release.description || "",
    IsLatestVersion: release.isLatestVersion ?? "",
    RetentionPeriod: release.retentionPeriod ?? "",
    RetentionAction: release.retentionAction || ""
  };
}
function formatProcessListRow(release, includeFolderId = false) {
  const row = {
    ...formatProcess(release),
    FolderKey: release.folderKey || "",
    FolderPath: release.organizationUnitFullyQualifiedName || ""
  };
  return includeFolderId ? { ...row, FolderId: release.organizationUnitId ?? 0 } : row;
}
function formatProcessDetail(release) {
  return {
    Key: release.key || "",
    Name: release.name || "",
    ProcessKey: release.processKey || "",
    ProcessVersion: release.processVersion || "",
    Description: release.description || "",
    IsLatestVersion: release.isLatestVersion ?? "",
    ProcessType: release.processType || "",
    EntryPointPath: release.entryPointPath || "",
    InputArguments: release.inputArguments || "",
    FolderKey: release.folderKey || "",
    FolderPath: release.organizationUnitFullyQualifiedName || "",
    AutoUpdate: release.autoUpdate ?? "",
    TargetFramework: release.targetFramework || "",
    JobPriority: release.jobPriority || "",
    SpecificPriorityValue: release.specificPriorityValue ?? "",
    RetentionPeriod: release.retentionPeriod ?? "",
    RetentionAction: release.retentionAction || "",
    StaleRetentionPeriod: release.staleRetentionPeriod ?? "",
    StaleRetentionAction: release.staleRetentionAction || "",
    HiddenForAttendedUser: release.hiddenForAttendedUser ?? "",
    AutoCreateConnectedTriggers: release.autoCreateConnectedTriggers ?? ""
  };
}
function formatProcessResource(resource) {
  return {
    ResourceType: resource.resourceType || "",
    ResourceName: resource.resourceName || "",
    FolderPath: resource.folderFullyQualifiedName || "",
    ValidationResult: resource.validationResult || "",
    ValidationError: resource.validationError || "",
    IsOverwritable: resource.isOverwritable ?? false,
    ResourceKey: resource.resourceKey || "",
    Id: resource.id ?? null
  };
}
function formatReleaseVersion(version) {
  return {
    Version: version.versionNumber || "",
    CreatedAt: version.creationTime?.toISOString() || "",
    ReleaseName: version.releaseName || "",
    ReleaseId: version.releaseId ?? 0,
    Id: version.id ?? null
  };
}
