function formatQueueItem(item) {
  return {
    Id: item.id ?? "",
    Key: item.key ?? "",
    UniqueKey: item.uniqueKey ?? "",
    Reference: item.reference ?? "",
    Status: item.status ?? "",
    Priority: item.priority ?? "",
    QueueDefinitionName: item.queueDefinition?.name ?? "",
    QueueDefinitionKey: item.queueDefinition?.key ?? "",
    CreationTime: item.creationTime ? new Date(item.creationTime).toISOString() : "",
    StartProcessing: item.startProcessing ? new Date(item.startProcessing).toISOString() : "",
    EndProcessing: item.endProcessing ? new Date(item.endProcessing).toISOString() : "",
    Progress: item.progress ?? ""
  };
}
function formatQueueItemDetail(item) {
  return {
    ...formatQueueItem(item),
    ReviewStatus: item.reviewStatus ?? "",
    DueDate: item.dueDate ? new Date(item.dueDate).toISOString() : "",
    RiskSlaDate: item.riskSlaDate ? new Date(item.riskSlaDate).toISOString() : "",
    DeferDate: item.deferDate ? new Date(item.deferDate).toISOString() : "",
    Encrypted: item.encrypted ?? false,
    SpecificContent: item.specificContent ?? {},
    Output: item.output ?? {},
    OutputData: item.outputData ?? "",
    Analytics: item.analytics ?? {},
    AnalyticsData: item.analyticsData ?? "",
    ProcessingExceptionType: item.processingExceptionType ?? "",
    ProcessingExceptionReason: item.processingException?.reason ?? "",
    SecondsInPreviousAttempts: item.secondsInPreviousAttempts ?? 0,
    RetryNumber: item.retryNumber ?? 0,
    AncestorId: item.ancestorId ?? null,
    CreatorJobKey: item.creatorJobKey ?? "",
    ExecutorJobKey: item.executorJobKey ?? "",
    RobotKey: item.robot?.key ?? ""
  };
}
function formatReviewer(user) {
  return {
    Key: user.key ?? "",
    UserName: user.userName ?? "",
    FullName: user.fullName ?? "",
    EmailAddress: user.emailAddress ?? "",
    IsActive: user.isActive ?? false
  };
}
