function parseDateOption(value, optionName, errorContext) {
  if (value === undefined) {
    return;
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: errorContext,
      Instructions: `Invalid ${optionName} '${value}'. Provide ISO 8601 format (e.g., '2026-03-15T09:00:00Z').`
    });
    processContext.exit(1);
    return;
  }
  return parsed;
}
async function resolveItems(api, keys) {
  const resolved = [];
  for (const key of keys) {
    const item = await api.queueItemsGetByUniqueKey({ uniqueKey: key });
    if (!item?.id || !item.rowVersion) {
      throw new Error(`Queue item '${key}' not found.`);
    }
    resolved.push({ id: item.id, rowVersion: item.rowVersion });
  }
  return resolved;
}
