function parseOptionalMinutes(value, optionName, errorMessage2) {
  if (value === undefined) {
    return;
  }
  const parsed = Number(value);
  if (!/^\d+$/.test(value) || !Number.isSafeInteger(parsed)) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: errorMessage2,
      Instructions: `${optionName} must be a non-negative integer.`
    });
    processContext.exit(1);
    return;
  }
  return parsed;
}
