var ROLE_TYPE_ALLOWLIST = ["Tenant", "Folder"];
function parseUserRolePrincipalType(value) {
  switch (value.toLowerCase()) {
    case "user":
    case "directoryuser":
    case "directory-user":
      return "User";
    case "group":
    case "directorygroup":
    case "directory-group":
      return "Group";
    case "robot":
    case "directoryrobot":
    case "directory-robot":
      return "Robot";
    case "machine":
      return "Machine";
    case "externalapplication":
    case "external-application":
    case "directoryexternalapplication":
    case "directory-external-application":
      return "ExternalApplication";
    default:
      return;
  }
}
