    if (options.state && !VALID_STATES.includes(options.state)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Invalid --state value",
        Instructions: `Valid states: ${VALID_STATES.join(", ")}`
      });
      processContext.exit(1);
      return;
    }
    const filters = ["(Robot/ProvisionType eq '1')"];
    if (options.state) {
      filters.push(`State eq '${options.state}'`);
    } else {
      filters.push("State ne 'Disconnected'");
    }
    if (options.machineName) {
      const sanitized = options.machineName.replace(/'/g, "''");
      filters.push(`contains(MachineName, '${sanitized}')`);
    }
    const $filter = filters.length > 0 ? filters.join(" and ") : undefined;
    const $top = parseInt(options.limit || "50", 10);
    const $skip = parseInt(options.offset || "0", 10);
