function parseTargetSpec(spec) {
  const parts = spec.split(",").map((p) => p.trim()).filter((p) => p.length > 0);
  if (parts.length === 0) {
    throw new Error("--target spec cannot be empty");
  }
  const out = {};
  for (const part of parts) {
    const eq = part.indexOf("=");
    if (eq === -1) {
      throw new Error(`Invalid --target part '${part}': expected 'key=value'`);
    }
    const key = part.slice(0, eq).trim().toLowerCase();
    const value = part.slice(eq + 1).trim();
    if (!value) {
      throw new Error(`--target field '${key}' value cannot be empty`);
    }
    switch (key) {
      case "machine":
        if (!isGuid(value)) {
          throw new Error(`Invalid machine key '${value}' in --target: must be a UUID`);
        }
        if (out.machineKey) {
          throw new Error(`--target has duplicate 'machine' field`);
        }
        out.machineKey = value;
        break;
      case "user":
        if (!isGuid(value)) {
          throw new Error(`Invalid user key '${value}' in --target: must be a UUID`);
        }
        if (out.userKey) {
          throw new Error(`--target has duplicate 'user' field`);
        }
        out.userKey = value;
        break;
      case "session": {
        const n = Number(value);
        if (!Number.isInteger(n) || n <= 0) {
          throw new Error(`Invalid session ID '${value}' in --target: must be a positive integer`);
        }
        if (out.sessionId !== undefined) {
          throw new Error(`--target has duplicate 'session' field`);
        }
        out.sessionId = n;
        break;
      }
      default:
        throw new Error(`Unknown --target field '${key}'. Expected: machine, user, session`);
    }
  }
  if (!out.machineKey && !out.userKey && out.sessionId === undefined) {
    throw new Error("--target must include at least one of: machine, user, session");
  }
  return out;
}
