async function injectQueueDefinitionKeys(triggers, ctx) {
  const ids = [
    ...new Set(triggers.map((t) => t.queueDefinitionId).filter((id) => id != null && id > 0))
  ];
  if (ids.length === 0)
    return;
  const [apiError, api] = await catchError(createApiClient(QueueDefinitionsApi, {
    tenant: ctx.tenant,
    folderPath: ctx.folderPath,
    folderKey: ctx.folderKey
  }));
  if (apiError) {
    logger.warn(`Failed to resolve queue keys: ${apiError.message}`);
    return;
  }
  const idToKey = new Map;
  const results = await Promise.all(ids.map(async (id) => {
    const [getError, queue] = await catchError(api.queueDefinitionsGetById({ key: id }));
    return { id, key: !getError ? queue?.key : undefined };
  }));
  for (const { id, key } of results) {
    if (key)
      idToKey.set(id, key);
  }
  for (const trigger of triggers) {
    if (trigger.queueDefinitionId != null) {
      const key = idToKey.get(trigger.queueDefinitionId);
      if (key) {
        trigger.queueDefinitionKey = key;
      }
    }
  }
}

// src/utils/credential-store-resolver.ts
async function resolveCredentialStore2(tenant, credentialStoreKey) {
  const [apiError, api] = await catchError(createApiClient(CredentialStoresApi, { tenant }));
  if (apiError)
    throw apiError;
  const [getError, result] = await catchError(api.credentialStoresGet({
    $filter: `Key eq ${credentialStoreKey}`,
    $top: 1
  }));
  if (getError)
    throw new Error(await extractErrorMessage(getError));
  const store = result.value?.[0];
  if (!store?.id) {
    throw new Error(`Credential store with key '${credentialStoreKey}' not found. Use 'credential-stores list' to find it.`);
  }
  return store;
}

